/* ===================================================== */
/* Long-form content polish — turn the plain block stream */
/* into a structured, professional reading experience     */
/* ===================================================== */

.entry-content {
	--content-measure: 68ch;
}

/* Section rhythm: every H2 starts a new "section" with breathing room + a subtle rule above it (except the first) */
.entry-content h2 {
	margin-top: 64px;
	margin-bottom: 20px;
	padding-top: 32px;
	border-top: 1px solid #DCE3E1;
	max-width: var(--content-measure);
}
.entry-content > .wp-block-heading:first-of-type,
.entry-content h2:first-child {
	border-top: none;
	padding-top: 0;
	margin-top: 8px;
}
.entry-content h3 {
	margin-top: 36px;
	margin-bottom: 12px;
	max-width: var(--content-measure);
}
.entry-content p {
	max-width: var(--content-measure);
}

/* Lists: give them a teal marker instead of default bullets/decimal grey */
.entry-content ul:not(.wp-block-kadence-icon-list-container):not(.footer-navigation ul):not(.menu) {
	max-width: var(--content-measure);
	padding-left: 0;
	list-style: none;
}
.entry-content ul:not(.wp-block-kadence-icon-list-container):not(.footer-navigation ul):not(.menu) > li {
	position: relative;
	padding-left: 28px;
	margin-bottom: 10px;
	line-height: 1.6;
}
.entry-content ul:not(.wp-block-kadence-icon-list-container):not(.footer-navigation ul):not(.menu) > li::before {
	content: "";
	position: absolute;
	left: 0;
	top: 0.55em;
	width: 8px;
	height: 8px;
	border-radius: 2px;
	background: var(--global-palette1);
}
.entry-content ol {
	max-width: var(--content-measure);
	padding-left: 22px;
}
.entry-content ol > li {
	padding-left: 6px;
	margin-bottom: 10px;
	line-height: 1.6;
}
.entry-content ol > li::marker {
	color: var(--global-palette1);
	font-family: "Space Grotesk", sans-serif;
	font-weight: 600;
}

/* FAQ accordion (native <details>/<summary>) — instrument-panel styling instead of the browser default disclosure triangle */
.entry-content details {
	max-width: var(--content-measure);
	border: 1px solid #DCE3E1;
	border-radius: 6px;
	margin-bottom: 10px;
	background: var(--global-palette9);
	overflow: hidden;
}
.entry-content details + details {
	margin-top: -1px;
}
.entry-content details summary {
	list-style: none;
	cursor: pointer;
	padding: 16px 44px 16px 18px;
	font-family: "IBM Plex Sans", sans-serif;
	font-weight: 600;
	font-size: 16px;
	color: var(--global-palette3);
	position: relative;
	line-height: 1.4;
}
.entry-content details summary::-webkit-details-marker {
	display: none;
}
.entry-content details summary::after {
	content: "+";
	position: absolute;
	right: 18px;
	top: 50%;
	transform: translateY(-50%);
	font-family: "Space Grotesk", sans-serif;
	font-size: 20px;
	font-weight: 600;
	color: var(--global-palette1);
	transition: transform 0.15s ease;
}
.entry-content details[open] summary::after {
	transform: translateY(-50%) rotate(45deg);
}
.entry-content details summary:hover {
	background: var(--global-palette8);
}
.entry-content details[open] summary {
	border-bottom: 1px solid #DCE3E1;
}
.entry-content details p {
	padding: 14px 18px 18px;
	margin: 0;
	color: var(--global-palette4);
	line-height: 1.65;
	max-width: none;
}

/* Table refinement */
.entry-content .wp-block-table {
	max-width: var(--content-measure);
	overflow-x: auto;
}
.entry-content table {
	width: 100%;
	border-radius: 6px;
	overflow: hidden;
}
.entry-content table td {
	padding: 10px 14px;
	color: var(--global-palette4);
}
.entry-content table th {
	padding: 10px 14px;
	text-align: left;
}
.entry-content table tbody tr:nth-child(even) td {
	background: var(--global-palette8);
}

/* Tool-link columns only. Section columns stay flat. */
.imc-tools .wp-block-kadence-column {
	background: var(--global-palette9);
	border: 1px solid #DCE3E1;
	border-radius: 6px;
	padding: 24px;
	transition: border-color 0.15s ease;
}
.imc-tools .wp-block-kadence-column:hover {
	border-color: var(--global-palette1);
}
.imc-tools .wp-block-kadence-column p {
	max-width: none;
}
.imc-tools .kt-btn-inner-text {
	font-weight: 600;
}

/* Full-bleed Kadence sections inside the normal content column */
.entry-content > .alignfull,
.entry-content > .wp-block-kadence-rowlayout.alignfull {
	width: 100vw;
	max-width: 100vw;
	margin-left: calc(50% - 50vw);
	margin-right: calc(50% - 50vw);
}

.imc-hero .kt-inside-inner-col {
	text-align: center;
}
.imc-hero p,
.imc-hero h1,
.imc-hero .wp-block-kadence-advancedheading {
	margin-left: auto;
	margin-right: auto;
}
.imc-hero .wp-block-shortcode,
.imc-hero .imc-calc,
.imc-hero .wp-block-kadence-advancedbtn {
	text-align: initial;
}
.imc-section h2,
.imc-hero h1 {
	border-top: none;
	padding-top: 0;
	margin-top: 0;
}
.imc-section .kt-accordion-wrap,
.imc-section .wp-block-table,
.imc-section .wp-block-kadence-advancedheading,
.imc-section p,
.imc-section ul,
.imc-section ol {
	max-width: 68ch;
}

/* Trust badge row (added near the hero) */
.imc-trust-bar {
	display: flex;
	flex-wrap: wrap;
	gap: 10px;
	margin: 16px 0 24px;
	max-width: 560px;
	margin-left: auto;
	margin-right: auto;
}
.imc-trust-bar__item {
	display: inline-flex;
	align-items: center;
	gap: 6px;
	font-family: "IBM Plex Sans", sans-serif;
	font-size: 13px;
	font-weight: 500;
	color: var(--global-palette5);
	background: var(--global-palette8);
	border: 1px solid #DCE3E1;
	border-radius: 999px;
	padding: 6px 14px;
}
.imc-trust-bar__item::before {
	content: "";
	width: 6px;
	height: 6px;
	border-radius: 50%;
	background: var(--global-palette1);
	flex-shrink: 0;
}

@media (max-width: 599px) {
	.entry-content h2 { margin-top: 44px; }
}

