/* ===================================================== */
/* Tool surface: instrument stage, then a reference sheet */
/* ===================================================== */

/* The white article card is what made every page look like a post. */
body:has(.imc-hero) .entry.content-bg,
body:has(.imc-section) .entry.content-bg {
	background: transparent !important;
	box-shadow: none !important;
}
body:has(.imc-hero) .entry-content-wrap,
body:has(.imc-section) .entry-content-wrap {
	padding: 0 !important;
}

/* Hero: the calculator is the page. */
.imc-hero {
	background: #F4F6F5 !important;
}
.imc-hero .kt-row-column-wrap {
	padding-top: 36px !important;
	padding-bottom: 72px !important;
}
.imc-hero .kt-inside-inner-col {
	max-width: 720px;
	margin-left: auto;
	margin-right: auto;
	text-align: center;
}
.imc-hero p,
.imc-hero h1,
.imc-hero .wp-block-kadence-advancedheading {
	margin-left: auto;
	margin-right: auto;
}
.imc-hero p {
	max-width: 58ch;
}
.imc-hero .wp-block-shortcode,
.imc-hero .imc-calc,
.imc-hero .wp-block-kadence-advancedbtn {
	text-align: initial;
}
.imc-hero .imc-calc {
	margin-top: 8px;
}

/* Reference copy sits on a full-width white sheet, centered. */
.imc-section {
	background: #FFFFFF !important;
}
.imc-section + .imc-section {
	box-shadow: inset 0 1px 0 #DCE3E1;
}
.imc-section .kt-row-column-wrap {
	padding-top: 56px !important;
	padding-bottom: 56px !important;
}
.imc-section .kt-inside-inner-col {
	max-width: 720px;
	margin-left: auto;
	margin-right: auto;
}
.imc-section h2,
.imc-hero h1,
.imc-section .wp-block-kadence-advancedheading,
.imc-hero .wp-block-kadence-advancedheading {
	border-top: none;
	padding-top: 0;
	margin-top: 0;
	max-width: none;
}
.imc-section .wp-block-kadence-advancedheading {
	margin-bottom: 16px;
}
.imc-section p,
.imc-section ul,
.imc-section ol,
.imc-section .wp-block-table,
.imc-section .kt-accordion-wrap,
.imc-section .wp-block-kadence-accordion {
	max-width: none;
}

/* Lists */
.entry-content ul:not(.wp-block-kadence-icon-list-container):not(.footer-navigation ul):not(.menu) {
	padding-left: 0;
	list-style: none;
}
.entry-content ul:not(.wp-block-kadence-icon-list-container):not(.footer-navigation ul):not(.menu) > li {
	position: relative;
	padding-left: 28px;
	margin-bottom: 10px;
	line-height: 1.6;
}
.entry-content ul:not(.wp-block-kadence-icon-list-container):not(.footer-navigation ul):not(.menu) > li::before {
	content: "";
	position: absolute;
	left: 0;
	top: 0.55em;
	width: 8px;
	height: 8px;
	border-radius: 2px;
	background: var(--global-palette1);
}
.entry-content ol {
	padding-left: 22px;
}
.entry-content ol > li {
	padding-left: 6px;
	margin-bottom: 10px;
	line-height: 1.6;
}
.entry-content ol > li::marker {
	color: var(--global-palette1);
	font-family: "Space Grotesk", sans-serif;
	font-weight: 600;
}

/* Short labeled notes, not blog paragraphs. */
.imc-section p:has(> strong:first-child) {
	padding: 2px 0 2px 14px;
	border-left: 2px solid #DCE3E1;
}

/* Homepage formula readout. */
.home .entry-content > section:nth-of-type(3) .kt-inside-inner-col > p:nth-child(3) {
	border: 1px solid #DCE3E1;
	border-left: 1px solid #DCE3E1;
	border-radius: 6px;
	background: #F4F6F5;
	padding: 22px 24px;
	margin-top: 8px;
	margin-bottom: 20px;
	text-align: center;
	font-family: "Space Grotesk", sans-serif;
	font-size: 28px;
	line-height: 1.3;
	color: #1A2421;
}

/* FAQ kept as a hairline list */
.entry-content details {
	border: 1px solid #DCE3E1;
	border-radius: 6px;
	margin-bottom: 10px;
	background: #FFFFFF;
	overflow: hidden;
}
.entry-content details + details {
	margin-top: -1px;
}
.entry-content details summary {
	list-style: none;
	cursor: pointer;
	padding: 16px 44px 16px 18px;
	font-family: "IBM Plex Sans", sans-serif;
	font-weight: 600;
	font-size: 16px;
	color: #1A2421;
	position: relative;
	line-height: 1.4;
}
.entry-content details summary::-webkit-details-marker {
	display: none;
}
.entry-content details summary::after {
	content: "+";
	position: absolute;
	right: 18px;
	top: 50%;
	transform: translateY(-50%);
	font-family: "Space Grotesk", sans-serif;
	font-size: 20px;
	font-weight: 600;
	color: #0E5C52;
}
.entry-content details[open] summary::after {
	transform: translateY(-50%) rotate(45deg);
}
.entry-content details summary:hover {
	background: #F4F6F5;
}
.entry-content details[open] summary {
	border-bottom: 1px solid #DCE3E1;
}
.entry-content details p {
	padding: 14px 18px 18px;
	margin: 0;
	line-height: 1.65;
	max-width: none;
	border-left: none;
}

/* Category table as a scale, not a spreadsheet. */
.entry-content .wp-block-table {
	overflow-x: auto;
	max-width: none;
}
.entry-content table {
	width: 100%;
	border: none;
	border-radius: 0;
	overflow: visible;
}
.entry-content table th,
.entry-content table td {
	border: none;
	border-bottom: 1px solid #DCE3E1;
	padding: 14px 12px;
	background: transparent;
}
.entry-content table th {
	text-align: left;
	background: transparent;
	color: #3B5B6D;
	font-size: 13px;
}
.entry-content table td:first-child {
	position: relative;
	width: 46%;
	padding-left: 22px;
	font-family: "Space Grotesk", sans-serif;
	font-weight: 600;
	color: #1A2421;
}
.entry-content table tbody tr:nth-child(even) td {
	background: transparent;
}
.home .entry-content > section:nth-of-type(4) table tbody tr td:first-child::before {
	content: "";
	position: absolute;
	left: 0;
	top: 50%;
	width: 10px;
	height: 10px;
	border-radius: 2px;
	transform: translateY(-50%);
}
.home .entry-content > section:nth-of-type(4) table tbody tr:nth-child(1) td:first-child::before { background: #3B7DD8; }
.home .entry-content > section:nth-of-type(4) table tbody tr:nth-child(2) td:first-child::before { background: #0E5C52; }
.home .entry-content > section:nth-of-type(4) table tbody tr:nth-child(3) td:first-child::before { background: #C98A1F; }
.home .entry-content > section:nth-of-type(4) table tbody tr:nth-child(4) td:first-child::before { background: #C1591F; }
.home .entry-content > section:nth-of-type(4) table tbody tr:nth-child(5) td:first-child::before { background: #A83A2A; }
.home .entry-content > section:nth-of-type(4) table tbody tr:nth-child(6) td:first-child::before { background: #7A2420; }

/* Other calculators: a row under the reference sheet. */
.imc-tools {
	background: #FFFFFF;
	width: 100vw;
	max-width: 100vw;
	margin-left: calc(50% - 50vw);
	margin-right: calc(50% - 50vw);
}
.imc-tools .kt-row-column-wrap {
	max-width: 1080px !important;
	width: 100%;
	margin-left: auto !important;
	margin-right: auto !important;
	padding: 4px 24px 72px !important;
	box-sizing: border-box;
}
.imc-tools .wp-block-kadence-column {
	background: #FFFFFF;
	border: 1px solid #DCE3E1;
	border-radius: 6px;
	padding: 24px;
	transition: border-color 0.15s ease;
}
.imc-tools .wp-block-kadence-column:hover {
	border-color: #0E5C52;
}
.imc-tools .wp-block-kadence-column p {
	max-width: none;
}
.imc-tools .wp-block-kadence-column strong {
	display: inline-block;
	margin-bottom: 8px;
	font-family: "Space Grotesk", sans-serif;
	font-weight: 600;
	font-size: 20px;
	line-height: 1.25;
	color: #1A2421;
}
.imc-tools .kt-btn-inner-text {
	font-weight: 600;
}

/* Full-bleed sections inside the content column */
.entry-content > .alignfull,
.entry-content > .wp-block-kadence-rowlayout.alignfull {
	width: 100vw;
	max-width: 100vw;
	margin-left: calc(50% - 50vw);
	margin-right: calc(50% - 50vw);
}

@media (max-width: 767px) {
	.imc-hero .kt-row-column-wrap {
		padding-top: 24px !important;
		padding-bottom: 40px !important;
	}
	.imc-section .kt-row-column-wrap {
		padding-top: 36px !important;
		padding-bottom: 36px !important;
	}
	.imc-calc__result-number {
		font-size: 56px;
	}
	.home .entry-content > section:nth-of-type(3) .kt-inside-inner-col > p:nth-child(3) {
		font-size: 22px;
	}
	.imc-tools .kt-row-column-wrap {
		grid-template-columns: 1fr !important;
	}
}
